 function render(){
  if(!running)return;const rooms=[...new Map(selected.map(s=>[s.roomId,s])).values()],edges=focused?edgesFor(focused):[];
  controls.innerHTML=`<header class="lpSpatialTop"><div><strong>${options.purpose==='execution'?'Superficies intervenidas':'Seleccionar recintos y superficies'}</strong><small>Visor de arquitectura de Atlas · toca para seleccionar o quitar.</small></div><label>Piso<select data-pick-floor ${busy||options.purpose==='execution'?'disabled':''}>${pisos.map(p=>`<option value="${p.id}" ${p.id===currentLevel?'selected':''}>${esc(p.nombre)}</option>`).join('')}</select></label></header><div class="lpSpatialBottom"><div class="lpSpatialModes">${[['recinto',options.purpose==='plan'?'Ubicación del recinto':'Recinto completo'],['muros','Muros'],['cielos','Cielos'],['pavimentos','Pavimentos']].map(([v,l])=>`<button type="button" data-pick-mode="${v}" aria-pressed="${mode===v}">${l}</button>`).join('')}<button type="button" data-pick-draw>${drawing?'Cancelar trazado':mode==='muros'?'Delimitar tramo':'Delimitar área parcial'}</button>${drawing?'<button type="button" data-pick-finish>Guardar trazado</button><button type="button" data-pick-undo>Quitar punto</button>':''}</div><div class="lpSpatialContext" role="status">${busy?'Cargando el piso…':drawing?'Toca los extremos del tramo o los vértices del área; arrastra para desplazar y usa dos dedos para ampliar.':focused?esc(focused.code+' · '+focused.name):'Selecciona en el plano. Arrastra para desplazar y usa dos dedos para ampliar.'}</div>${mode==='muros'&&focused&&!drawing?`<div class="lpSpatialEdges" aria-label="Tramos del recinto">${edges.map((edge,i)=>`<button type="button" data-pick-edge="${i}">Tramo ${i+1}</button>`).join('')}</div>`:''}<p class="lpSpatialAxes" data-pick-axes role="status">Ejes: ${esc(axesText(selectionAxes(selected)))}</p><div class="lpSpatialSelection"><b>${rooms.length} recintos · ${selected.filter(s=>!s.locationOnly).length} superficies</b><div>${selected.map(s=>`<button type="button" data-pick-remove="${esc(s.id)}">${esc(s.code)} · ${esc(s.label)} ×</button>`).join('')}</div></div><footer><button type="button" data-pick-cancel ${busy?'disabled':''}>Cancelar</button><button type="button" class="primary" data-pick-apply ${busy?'disabled':''}>Aplicar selección</button></footer></div>`;
  const zoomControls=document.createElement('div');zoomControls.className='lpSpatialZoom';zoomControls.innerHTML='<button type="button" data-zoom=".7" aria-label="Ampliar plano">+</button><button type="button" data-zoom="1.4" aria-label="Alejar plano">−</button><button type="button" data-fit>Ver todo</button>';controls.querySelector('.lpSpatialTop').append(zoomControls);zoomControls.querySelectorAll('[data-zoom]').forEach(b=>b.onclick=()=>ctx.zoom?.(Number(b.dataset.zoom)));zoomControls.querySelector('[data-fit]').onclick=()=>ctx.fit?.();
  layout.disconnect();layout.observe(controls.querySelector('.lpSpatialTop'));layout.observe(controls.querySelector('.lpSpatialBottom'));
  controls.querySelector('[data-pick-floor]').onchange=async event=>{const next=event.target.value;if(selected.length&&selected.some(s=>s.level!==next)){if(!confirm('La actividad corresponde a un piso. ¿Cambiar de piso y reemplazar esta selección?')){event.target.value=currentLevel;return;}selected=[];}busy=true;render();try{await ctx.loadFloor(next);currentLevel=next;axesGrid=await loadAxesGrid(next).catch(()=>null);focused=null;drawing=null;}catch(error){ctx.toast(error.message);}finally{busy=false;render();paint();}};
  controls.querySelectorAll('[data-pick-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.pickMode;drawing=null;render();});
  controls.querySelectorAll('[data-pick-remove]').forEach(b=>b.onclick=()=>{selected=selected.filter(s=>s.id!==b.dataset.pickRemove);render();paint();});
  controls.querySelectorAll('[data-pick-edge]').forEach(b=>b.onclick=()=>toggleEdge(focused,edges[Number(b.dataset.pickEdge)],Number(b.dataset.pickEdge)));
  controls.querySelector('[data-pick-draw]').onclick=()=>{if(drawing)drawing=null;else if(!focused)ctx.toast('Toca primero el recinto donde intervendrás.');else drawing={room:focused,points:[]};render();paint();};
  controls.querySelector('[data-pick-finish]')?.addEventListener('click',()=>{if(drawing.points.length<(mode==='muros'?2:3))return ctx.toast('Marca al menos '+(mode==='muros'?'dos extremos.':'tres vértices.'));const geometry={type:mode==='muros'?'line':'polygon',points:drawing.points};if(!(ctx.footprint(drawing.room.id)?.rings||[]).some(r=>withinGeometry({type:'polygon',points:r.polygon,holes:r.holes},geometry)))return ctx.toast('El tramo cruza un límite o hueco del recinto. Ajusta sus puntos.');const scope=makeScope(drawing.room,geometry,'Intervención parcial delimitada');scope.manualGeometry=true;toggle(scope);drawing=null;render();paint();});
  controls.querySelector('[data-pick-undo]')?.addEventListener('click',()=>{drawing.points.pop();paint();});
  controls.querySelector('[data-pick-cancel]').onclick=()=>finish(null);controls.querySelector('[data-pick-apply]').onclick=()=>finish(clone(selected));paint();
 }
 function edgesFor(room){return (ctx.footprint(room.id)?.rings||[]).flatMap((ring,ringIndex)=>ring.polygon.map((a,i)=>({a,b:ring.polygon[(i+1)%ring.polygon.length],ring:ringIndex,index:i})));}
 function makeScope(room,geometry,label){const fp=ctx.footprint(room.id),s=scopeFromGeometry(room,mode,geometry,ctx.source(room),ctx.scale(),fp?.quality,label);s.level=currentLevel;s.ejes=scopeAxes(s,axesGrid?.grid,{...axesGrid?.reference,nivel:currentLevel});if(mode==='recinto'&&options.purpose==='plan'){s.locationOnly=true;s.label='Ubicación sin superficies definidas';s.measurement=null;s.roomBoundary=s.geometry;}if(mode==='muros'){const ring=fp?.rings?.find(r=>r.polygon.some((a,i)=>geometry.points.every(p=>segmentDistance(p,a,r.polygon[(i+1)%r.polygon.length]).distance<.2)));if(ring){const edges=orientedEdges(ring.polygon,calibrate(axesGrid?.grid,axesGrid?.reference)),edge=edges.find(e=>geometry.points.every(p=>segmentDistance(p,...e.points).distance<.2));s.roomBoundary={type:'polygon',points:ring.polygon,holes:ring.holes};s.orientation=edge;s.label='Muro '+edge.label+' · contorno por verificar';}}return s;}
 function toggle(scope){if(options.allowed?.length){const parent=options.allowed.find(s=>s.id===scope.id)||options.allowed.find(s=>s.roomId===scope.roomId&&s.tipo===scope.tipo&&withinGeometry(s.geometry,scope.geometry));if(!parent)return ctx.toast('Esta superficie no pertenece al compromiso publicado.');scope.plannedScopeId=parent.id;}
  if(scope.tipo==='recinto')selected=selected.filter(s=>s.roomId!==scope.roomId||s.tipo==='recinto');else selected=selected.filter(s=>s.roomId!==scope.roomId||s.tipo!=='recinto');
  const previous=selected.find(s=>s.id===scope.id);if(previous)selected=selected.filter(s=>s.id!==scope.id);else selected.push(scope);render();paint();}
 function toggleEdge(room,edge,index){if(!edge)return;toggle(makeScope(room,{type:'line',points:[edge.a,edge.b]},'Tramo de muro '+(index+1)));}
 function choose(roomId,point){if(!running||busy)return;const room=ctx.room(roomId);if(drawing){const p=[round(point.x),round(point.y)],rings=ctx.footprint(drawing.room.id)?.rings||[];if(!rings.some(r=>insideRing(p,r.polygon,2)&&!(r.holes||[]).some(h=>insideRing(p,h,0))))return ctx.toast('Delimita la intervención dentro del recinto seleccionado.');drawing.points.push(p);paint();return;}if(!room)return ctx.toast('Toca un recinto identificado o un pasillo con contorno.');const changedFocus=focused?.id!==room.id;focused=room;
  if(mode==='muros'&&changedFocus){ctx.focus?.(room);render();return;}
  if(mode==='muros'){const edges=edgesFor(room),p=[point.x,point.y],nearest=edges.map((edge,i)=>({edge,i,d:segmentDistance(p,edge.a,edge.b).distance})).sort((a,b)=>a.d-b.d)[0],tolerance=12/(document.getElementById('svg').getScreenCTM()?.a||1);if(nearest&&nearest.d<tolerance)toggleEdge(room,nearest.edge,nearest.i);else render();return;}
  const rings=ctx.footprint(room.id)?.rings;if(!rings?.length)return ctx.toast('Este recinto requiere revisar su contorno antes de delimitar una intervención.');
  // Each connected part stays explicit; do not join disconnected spaces with an invented outline.
  for(const [i,ring] of rings.entries())toggle(makeScope(room,{type:'polygon',points:ring.polygon,holes:ring.holes},rings.length>1?'Parte '+(i+1):''));
 }
 async function finish(value){if(!running||busy)return;busy=true;try{await ctx.restore();}finally{running=false;busy=false;layout.disconnect();controls.hidden=true;document.body.classList.remove('lpPicking');document.body.style.removeProperty('--lp-picker-top');document.body.style.removeProperty('--lp-picker-bottom');layer.innerHTML='';const done=resolver;resolver=null;done(value);}}
 async function select(value={}){if(running)throw Error('Termina la selección en curso.');const result=new Promise(resolve=>{resolver=resolve;});options=value;selected=clone(value.scopes||[]);currentLevel=value.level||nivel.id;focused=null;mode=value.mode||'recinto';drawing=null;running=true;busy=true;document.body.classList.add('lpPicking');controls.hidden=false;render();try{await ctx.enter();await ctx.loadFloor(currentLevel);axesGrid=await loadAxesGrid(currentLevel).catch(()=>null);selected=selected.map(s=>({...s,ejes:scopeAxes(s,axesGrid?.grid,{...axesGrid?.reference,nivel:currentLevel})}));busy=false;render();}catch(error){busy=false;await finish(null);throw error;}return result;}
 window.addEventListener('keydown',event=>{if(running&&event.key==='Escape'){event.preventDefault();finish(null);}});
